DO $guard$ BEGIN IF current_user <> 'hms_cleanup' OR (session_user<>'postgres' AND NOT coalesce((SELECT ssl FROM pg_stat_ssl WHERE pid=pg_backend_pid()),false)) OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls OR rolcreaterole OR rolcreatedb)) OR has_schema_privilege(current_user,'public','CREATE') OR EXISTS(SELECT 1 FROM pg_class WHERE relnamespace='public'::regnamespace AND relkind='r' AND (has_table_privilege(current_user,oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR pg_has_role(relowner,'USAGE'))) OR has_function_privilege(current_user,'public.hms_create_demo_workspace(text)','EXECUTE') OR has_function_privilege(current_user,'public.hms_touch_demo_workspace(text)','EXECUTE') THEN RAISE EXCEPTION 'Restricted cleanup identity and TLS required'; END IF; END $guard$;